'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');

test('assignment supersedes additions at parent and child nodes', () => {
  const tree = new RangeTree([1, 2, 3, 4, 5, 6, 7, 8]);
  tree.add(0, 4, 7);
  tree.add(0, 8, 3);
  tree.assign(0, 8, -10);
  tree.add(0, 8, 2);
  assert.equal(tree.sum(2, 6), -32);
  assert.deepEqual(tree.toArray(), Array(8).fill(-8));
});

test('partial maxima preserve negative values', () => {
  const tree = new RangeTree([-7, -3, -9]);
  assert.equal(tree.max(0, 2), -3);
  assert.equal(tree.max(2, 3), -9);
});

test('search pushes assignment and addition before descending', () => {
  const assigned = new RangeTree([0, 0, 0, 0]);
  assigned.assign(0, 4, 5);
  assert.equal(assigned.firstAtLeast(1, 5), 1);
  const added = new RangeTree([10, 5, 5, 5]);
  added.add(0, 4, -5);
  assert.equal(added.firstAtLeast(1, 3), -1);
  assert.equal(added.firstAtLeast(0, 5), 0);
});

test('mixed updates and queries agree with a deterministic array model', () => {
  let seed = 0x12345678;
  const random = limit => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % limit;
  };
  for (const size of [1, 2, 3, 5, 8, 17, 33]) {
    const values = Array.from({ length: size }, () => random(41) - 20);
    const tree = new RangeTree(values);
    for (let step = 0; step < 300; step++) {
      let l = random(size + 1);
      let r = random(size + 1);
      if (l > r) [l, r] = [r, l];
      if (step % 7 === 0) { l = 0; r = size; }
      const value = random(41) - 20;
      const assigning = random(2) === 0;
      assert.equal(assigning ? tree.assign(l, r, value) : tree.add(l, r, value), undefined);
      for (let i = l; i < r; i++) values[i] = assigning ? value : values[i] + value;
      // Search first: materializing or querying first would hide stale child tags.
      for (const threshold of [-Infinity, -21, -1, 0, 1, 21, Infinity]) {
        for (let lo = 0; lo <= size; lo++) {
          const expected = values.findIndex((v, i) => i >= lo && v >= threshold);
          assert.equal(tree.firstAtLeast(lo, threshold), expected, `search size=${size} step=${step} lo=${lo} x=${threshold}`);
        }
      }
      for (let start = 0; start <= size; start++) {
        let sum = 0;
        let max = -Infinity;
        for (let end = start; end <= size; end++) {
          assert.equal(tree.sum(start, end), sum, `sum size=${size} step=${step} range=${start}:${end}`);
          assert.equal(tree.max(start, end), max, `max size=${size} step=${step} range=${start}:${end}`);
          if (end < size) { sum += values[end]; max = Math.max(max, values[end]); }
        }
      }
      for (let i = 0; i < size; i++) assert.equal(tree.get(i), values[i]);
      assert.deepEqual(tree.toArray(), values);
    }
  }
});

test('validation, empty ranges, length and independent arrays retain their contract', () => {
  for (const values of [[], null, {}, [NaN], [Infinity], [-Infinity], ['1'], new Array(2)]) {
    assert.throws(() => new RangeTree(values), RangeError);
  }
  const input = [2, -4, 6];
  const tree = new RangeTree(input);
  input[0] = 999;
  assert.equal(tree.length, 3);
  assert.throws(() => { tree.length = 9; }, TypeError);
  for (const [l, r] of [[-1, 1], [0, 4], [2, 1], [0.5, 2], [0, NaN], ['0', 1], [0, Infinity]]) {
    for (const method of ['assign', 'add', 'sum', 'max']) {
      assert.throws(() => tree[method](l, r, 7), RangeError);
    }
  }
  for (const v of [NaN, Infinity, -Infinity, '1', null, undefined]) {
    for (const method of ['assign', 'add']) {
      assert.throws(() => tree[method](0, 3, v), RangeError);
      assert.throws(() => tree[method](1, 1, v), RangeError);
    }
  }
  for (const i of [-1, 3, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.get(i), RangeError);
  for (const lo of [-1, 4, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.firstAtLeast(lo, 0), RangeError);
  for (const x of [NaN, '0', null, undefined]) assert.throws(() => tree.firstAtLeast(0, x), RangeError);
  for (let i = 0; i <= 3; i++) {
    assert.equal(tree.assign(i, i, 9), undefined);
    assert.equal(tree.add(i, i, -9), undefined);
    assert.equal(tree.sum(i, i), 0);
    assert.equal(tree.max(i, i), -Infinity);
  }
  assert.equal(tree.firstAtLeast(0, -Infinity), 0);
  assert.equal(tree.firstAtLeast(0, Infinity), -1);
  assert.equal(tree.firstAtLeast(3, -Infinity), -1);
  const output = tree.toArray();
  output[1] = 999;
  assert.deepEqual(tree.toArray(), [2, -4, 6]);
});

